import { getMorbisGlobals } from './shared/types.js';
import { colors, injectCSS } from '../shared/ui/index.js';

const g = getMorbisGlobals();

interface CpptFilterState {
  search: string;
  dokter: string;
  tanggalAwal: string;
  tanggalAkhir: string;
}

const CPPT_STYLE_ID = 'ext-cppt-search-style';
const CPPT_NO_RESULTS_CLASS = 'ext-cppt-no-results';

type CpptPageType = 'rajal' | 'ranap' | null;

function getCpptPageType(): CpptPageType {
  const path = window.location.pathname;
  if (/\/admisi\/pelaksanaan_pelayanan\/cppt\/?$/.test(path)) return 'rajal';
  if (/\/admisi\/detail-rawat-inap\/cppt\/?$/.test(path)) return 'ranap';
  return null;
}

function isCpptTable(table: HTMLTableElement): boolean {
  const byId = table.id === 'history_cppt';
  if (byId) return true;

  const firstRow = table.querySelector('tr');
  if (firstRow) {
    const texts = Array.from(firstRow.querySelectorAll('th, td')).map(
      (c) => c.textContent?.trim().toLowerCase() || '',
    );
    const keywords = ['waktu', 'penginput', 'subyektif', 'obyektif', 'assessment', 'instruksi'];
    const matchCount = keywords.filter((k) => texts.some((t) => t.includes(k))).length;
    if (matchCount >= 2) return true;
  }

  if (table.textContent?.toLowerCase().includes('cppt')) return true;

  return false;
}

function findCpptTables(): HTMLTableElement[] {
  return Array.from(document.querySelectorAll<HTMLTableElement>('table')).filter(isCpptTable);
}

function getHeaderTexts(table: HTMLTableElement): string[] {
  const headerRow = table.querySelector('thead tr') || table.querySelector('tr');
  if (!headerRow) return [];
  return Array.from(headerRow.querySelectorAll('th, td'))
    .map((h) => h.textContent?.trim() || '')
    .filter((t) => t.length > 0);
}

function getColumnIndex(headers: string[], ...keywords: string[]): number {
  for (const kw of keywords) {
    const idx = headers.findIndex((h) => h.toLowerCase().includes(kw));
    if (idx !== -1) return idx;
  }
  return -1;
}

